    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: A 2-month-old girl presents with a barking cough, hoarseness, and inspiratory stridor. The parents report a low-grade fever and rhinorrhea for the past two days. What is the most likely pathogen?', '["Streptococcus pneumoniae", "Respiratory Syncytial Virus (RSV)", "Parainfluenza virus", "Haemophilus influenzae type b"]', 2, 'Croup is most commonly caused by the Parainfluenza virus. It presents with a seal-like barking cough and inspiratory stridor due to subglottic narrowing. (Nelson Essentials)'),
    (v_topic_id, '2: What classic radiographic sign is associated with Croup on an anteroposterior (AP) neck X-ray?', '["Thumbprint sign", "Steeple sign", "Sail sign", "Water bottle sign"]', 1, 'The steeple sign (subglottic narrowing) is seen in croup on an AP neck X-ray, though the diagnosis is primarily clinical. (Blueprints)'),
    (v_topic_id, '3: A 2-year-old with a barking cough and stridor at rest is brought to the emergency department. What is the most appropriate initial medical management?', '["Albuterol inhaler", "Intravenous antibiotics", "Immediate intubation", "Nebulized racemic epinephrine and oral dexamethasone"]', 3, 'Moderate to severe croup (stridor at rest) is treated with corticosteroids (e.g., dexamethasone) to reduce inflammation and nebulized epinephrine for rapid temporary relief of airway edema. (BRS Pediatrics)'),
    (v_topic_id, '4: An unimmunized 2-year-old presents with sudden onset of high fever, drooling, dysphagia, and is sitting leaning forward (tripod position). What is the most important NEXT step in management?', '["Perform a thorough oral exam with a tongue depressor", "Administer inhaled albuterol", "Obtain a lateral neck X-ray immediately", "Keep the child calm and prepare for artificial airway placement in the OR"]', 3, 'This is acute epiglottitis. The priority is securing the airway. Agitating the child (e.g., using a tongue depressor) can cause sudden fatal airway obstruction. (Nelson Essentials)'),
    (v_topic_id, '5: Historically, which pathogen was the most common cause of acute epiglottitis before widespread immunization?', '["Parainfluenza virus", "Staphylococcus aureus", "Streptococcus pyogenes", "Haemophilus influenzae type b"]', 3, 'Hib was the classic cause. Today, due to the Hib vaccine, Streptococcus pyogenes and Staphylococcus aureus are increasingly responsible in immunized populations. (Blueprints)'),
    (v_topic_id, '6: What classic radiographic sign is seen on a lateral neck X-ray in a child with epiglottitis?', '["Deep sulcus sign", "Silhouette sign", "Steeple sign", "Thumbprint sign"]', 3, 'The thumbprint sign represents an enlarged, swollen epiglottis protruding into the airway on a lateral neck radiograph. (Case Files Pediatrics)'),
    (v_topic_id, '7: A 5-year-old girl presents in the winter with a 3-day history of rhinorrhea and low-grade fever, which has progressed to tachypnea, wheezing, and subcostal retractions. What is the most likely diagnosis?', '["Bronchiolitis", "Asthma", "Croup", "Pertussis"]', 0, 'Bronchiolitis, typically caused by RSV in children <2 years old, presents with upper respiratory symptoms progressing to lower respiratory tract signs like wheezing and tachypnea. (Nelson Essentials)'),
    (v_topic_id, '8: What is the mainstay of treatment for a typical, uncomplicated case of viral bronchiolitis in a 6-year-old?', '["Azithromycin", "Oral corticosteroids", "Inhaled albuterol every 4 hours", "Supportive care (hydration and oxygen if hypoxic)"]', 3, 'Current AAP guidelines recommend against the routine use of bronchodilators, corticosteroids, or antibiotics for bronchiolitis. Treatment is primarily supportive. (AAP Guidelines / Blueprints)'),
    (v_topic_id, '9: Which prophylactic monoclonal antibody is indicated for infants at high risk for severe RSV bronchiolitis (e.g., premature infants, those with hemodynamically significant congenital heart disease)?', '["Omalizumab", "Rituximab", "Infliximab", "Palivizumab"]', 3, 'Palivizumab is an anti-RSV monoclonal antibody given monthly during RSV season to high-risk infants. (BRS Pediatrics)'),
    (v_topic_id, '10: A 10-year-old with a history of eczema presents with recurrent episodes of nocturnal coughing and expiratory wheezing. The symptoms are reversible with an inhaled medication. What is the most likely diagnosis?', '["Cystic Fibrosis", "Vocal cord dysfunction", "Asthma", "Gastroesophageal Reflux Disease"]', 2, 'Asthma is characterized by reversible airway obstruction, airway hyperresponsiveness, and inflammation. It often presents with wheezing and nocturnal cough. (Nelson Essentials)'),
    (v_topic_id, '11: According to asthma guidelines, what is the preferred first-line long-term controller medication for persistent asthma in children?', '["Long-acting beta-agonists (LABA)", "Inhaled corticosteroids (ICS)", "Oral systemic corticosteroids", "Leukotriene receptor antagonists (e.g., Montelukast)"]', 1, 'Inhaled corticosteroids are the most effective long-term controller therapy for all age groups with persistent asthma. (NHLBI/Blueprints)'),
    (v_topic_id, '12: A 3-year-old child with acute severe asthma exacerbation is not responding to continuous nebulized albuterol and ipratropium. What systemic medication should be administered next?', '["Theophylline", "Intravenous antibiotics", "Intravenous or oral corticosteroids (e.g., Methylprednisolone)", "Omalizumab"]', 2, 'Systemic corticosteroids reduce airway inflammation and are critical in the management of acute severe asthma exacerbations. (Nelson Essentials)'),
    (v_topic_id, '13: A 5-year-old presents with sudden onset of high fever, productive cough, chest pain, and lobar consolidation on chest X-ray. What is the most likely bacterial cause?', '["Streptococcus pneumoniae", "Staphylococcus aureus", "Mycoplasma pneumoniae", "Haemophilus influenzae"]', 0, 'Streptococcus pneumoniae is the most common cause of typical, community-acquired bacterial pneumonia in children beyond the neonatal period. (Blueprints)'),
    (v_topic_id, '14: A school-aged child (8-year-old) presents with a gradual onset of low-grade fever, malaise, headache, and a persistent hacking cough. Chest X-ray shows diffuse, bilateral interstitial infiltrates. What is the most likely pathogen?', '["Streptococcus pneumoniae", "Respiratory Syncytial Virus", "Klebsiella pneumoniae", "Mycoplasma pneumoniae"]', 3, 'Mycoplasma pneumoniae is a leading cause of atypical ''''walking'''' pneumonia in school-aged children and adolescents. (Nelson Essentials)'),
    (v_topic_id, '15: An infant born via vaginal delivery develops a staccato cough, tachypnea, and peripheral eosinophilia at 4 weeks of age. Chest X-ray shows hyperinflation and diffuse infiltrates. What is the diagnosis?', '["Pertussis", "RSV bronchiolitis", "Chlamydia trachomatis pneumonia", "Group B Streptococcus pneumonia"]', 2, 'Chlamydia trachomatis pneumonia typically presents between 3 to 12 weeks of age with a staccato cough, afebrile presentation, and eosinophilia. (BRS Pediatrics)'),
    (v_topic_id, '16: What is the most common cause of pneumonia in neonates (birth to 28 days)?', '["Mycoplasma pneumoniae", "Streptococcus pneumoniae", "Respiratory Syncytial Virus", "Group B Streptococcus (GBS) and E. coli"]', 3, 'Neonatal pneumonia is most commonly caused by pathogens acquired from the maternal genital tract, including GBS, E. coli, and Listeria monocytogenes. (Blueprints)'),
    (v_topic_id, '17: A 5-year-old female infant with a history of meconium ileus presents with recurrent pulmonary infections and failure to thrive. A sweat chloride test is 85 mEq/L (Normal < 40). What is the underlying genetic defect?', '["Defect in ciliary dynein arms", "Mutation in the alpha-1 antitrypsin gene", "Mutation in the CFTR gene (e.g., delta F508)", "Mutation in the dystrophin gene"]', 2, 'Cystic fibrosis is caused by an autosomal recessive mutation in the CFTR gene, leading to defective chloride transport, thick secretions, and multi-organ dysfunction. (Nelson Essentials)'),
    (v_topic_id, '18: Which pathogen is the most common cause of severe, chronic lung infections and rapid decline in pulmonary function in older children and adults with Cystic Fibrosis?', '["Burkholderia cepacia", "Haemophilus influenzae", "Pseudomonas aeruginosa", "Staphylococcus aureus"]', 2, 'While S. aureus is common in infancy, Pseudomonas aeruginosa eventually colonizes the lungs of most CF patients and is a major determinant of morbidity and mortality. (Blueprints)'),
    (v_topic_id, '19: A 5-year-old with Cystic Fibrosis presents with steatorrhea, poor weight gain, and fat-soluble vitamin deficiencies. What is the required daily medical therapy to address this gastrointestinal manifestation?', '["Daily antibiotics", "Pancreatic enzyme replacement therapy", "Ursodeoxycholic acid", "Proton pump inhibitors"]', 1, 'Thick secretions block the pancreatic ducts, leading to exocrine pancreatic insufficiency. Exogenous pancreatic enzymes must be taken with meals. (BRS Pediatrics)'),
    (v_topic_id, '20: An unimmunized 3-month-old presents with severe paroxysms of coughing followed by a high-pitched inspiratory ''''whoop'''' and posttussive emesis. Laboratory tests reveal a significant lymphocytosis. Diagnosis?', '["Pertussis (Whooping cough)", "Foreign body aspiration", "Croup", "Chlamydial pneumonia"]', 0, 'Pertussis, caused by Bordetella pertussis, presents with paroxysmal cough, an inspiratory whoop, and marked lymphocytosis. (Nelson Essentials)'),
    (v_topic_id, '21: What is the antibiotic of choice for treating Pertussis and for post-exposure prophylaxis of close contacts?', '["Trimethoprim-sulfamethoxazole", "Ceftriaxone", "Amoxicillin", "A macrolide (e.g., Azithromycin)"]', 3, 'Macrolides are the first-line treatment. Early treatment may reduce symptom severity, and treating later reduces the period of communicability. (Blueprints)'),
    (v_topic_id, '22: A 8-year-old suddenly develops coughing, choking, and unilateral wheezing while eating peanuts. Physical exam reveals decreased breath sounds on the right side. What is the most definitive diagnostic and therapeutic step?', '["Flexible endoscopy", "Albuterol nebulizer", "Rigid bronchoscopy", "Chest CT scan"]', 2, 'A rigid bronchoscopy is both diagnostic and therapeutic for removing a foreign body from the pediatric airway. (Nelson Essentials)'),
    (v_topic_id, '23: In a child with a suspected lower airway foreign body, what specific radiographic views can be most helpful if the standard AP chest X-ray is normal?', '["Barium swallow", "Inspiratory/expiratory films or lateral decubitus films", "CT scan of the chest without contrast", "Lateral neck X-ray"]', 1, 'A foreign body can cause a ball-valve effect. Expiratory films will show air trapping (hyperinflation) on the affected side because air can enter but not exit. (Case Files Pediatrics)'),
    (v_topic_id, '24: A full-term infant born via elective cesarean section develops tachypnea and mild retractions shortly after birth. Chest X-ray shows fluid in the interlobar fissures and prominent perihilar streaking. The infant recovers in 48 hours with nasal CPAP. Diagnosis?', '["Respiratory Distress Syndrome (RDS)", "Neonatal Pneumonia", "Transient Tachypnea of the Newborn (TTN)", "Meconium Aspiration Syndrome"]', 2, 'TTN is caused by delayed clearance of fetal lung fluid, commonly seen in C-section deliveries without prior labor. It resolves quickly with supportive care. (Nelson Essentials)'),
    (v_topic_id, '25: A premature infant born at 28 weeks gestation develops severe respiratory distress immediately after birth. Chest X-ray reveals a diffuse reticulogranular (ground-glass) appearance and air bronchograms. What is the primary pathophysiology?', '["Aspiration of meconium", "Pulmonary hypoplasia", "Bacterial infection", "Surfactant deficiency"]', 3, 'Respiratory Distress Syndrome (RDS) in premature infants is due to insufficient production of surfactant by Type II pneumocytes, leading to alveolar collapse. (Blueprints)'),
    (v_topic_id, '26: A post-term infant is born through thick, pea-soup meconium. The infant is limp, apneic, and cyanotic at birth. What is the most common radiographic finding in Meconium Aspiration Syndrome?', '["Diffuse ground-glass opacities", "Patchy infiltrates with areas of hyperinflation and atelectasis", "A completely white-out lung", "Fluid in the horizontal fissure"]', 1, 'Meconium creates a ball-valve obstruction, causing areas of hyperinflation (air trapping) interspersed with areas of atelectasis. (Nelson Essentials)'),
    (v_topic_id, '27: A premature infant requires mechanical ventilation and oxygen therapy for 6 weeks due to severe RDS. The infant continues to require supplemental oxygen at 36 weeks postmenstrual age. What is the most likely diagnosis?', '["Persistent Pulmonary Hypertension", "Congenital Diaphragmatic Hernia", "Bronchopulmonary Dysplasia (BPD)", "Cystic Fibrosis"]', 2, 'BPD (chronic lung disease of prematurity) is defined by the need for supplemental oxygen at 28 days of life or 36 weeks postmenstrual age, resulting from lung injury due to barotrauma and oxygen toxicity. (Blueprints)'),
    (v_topic_id, '28: A 8-year-old snores loudly at night, has witnessed pauses in breathing, and exhibits daytime hyperactivity and poor school performance. Physical exam reveals ''''kissing'''' tonsils. What is the most likely diagnosis?', '["Central Sleep Apnea", "Attention Deficit Hyperactivity Disorder (ADHD) only", "Obstructive Sleep Apnea (OSA)", "Narcolepsy"]', 2, 'Adenotonsillar hypertrophy is the most common cause of pediatric OSA, which can present atypically with hyperactivity and neurobehavioral issues rather than daytime sleepiness. (Nelson Essentials)'),
    (v_topic_id, '29: Which of the following is the most important modifiable risk factor to prevent Sudden Infant Death Syndrome (SIDS)?', '["Placing the infant supine (on their back) to sleep", "Keeping the infant''s room very warm", "Bed-sharing with parents", "Using a soft mattress with bumper pads"]', 0, 'The ''Back to Sleep'' campaign demonstrated that supine sleep positioning dramatically reduces the incidence of SIDS. Soft bedding, overheating, and bed-sharing are risk factors. (AAP Guidelines)'),
    (v_topic_id, '30: A 2-month-old infant is brought to the ER after an episode where they became limp, cyanotic, and appeared to stop breathing for 20 seconds before recovering spontaneously. The infant is now completely well and exam is normal. This episode is best characterized as:', '["Sudden Infant Death Syndrome (SIDS)", "Normal infant behavior", "Brief Resolved Unexplained Event (BRUE)", "A typical seizure"]', 2, 'A BRUE (formerly ALTE) is characterized by an episode of cyanosis/pallor, absent/decreased breathing, marked change in tone, or altered responsiveness in an infant <1 year old, which resolves completely. (Nelson Essentials)'),
    (v_topic_id, '31: A 4-week-old infant has had an inspiratory stridor that is worse when crying or feeding, and improves when placed in a prone position. The infant is thriving and has no fever. What is the most likely diagnosis?', '["Laryngomalacia", "Vascular ring", "Croup", "Subglottic hemangioma"]', 0, 'Laryngomalacia is the most common cause of chronic stridor in infants. It is caused by supraglottic collapse during inspiration and usually resolves spontaneously by 18-24 months. (Blueprints)'),
    (v_topic_id, '32: A 6-month-old presents with a prolonged expiratory wheeze and a barking, ''''brassy'''' cough. The symptoms worsen with agitation and respiratory infections. Bronchoscopy reveals collapse of the trachea during expiration. Diagnosis?', '["Tracheomalacia", "Croup", "Asthma", "Foreign body aspiration"]', 0, 'Tracheomalacia involves structural weakness of the tracheal cartilage, causing collapse during expiration (when intrathoracic pressure is high), leading to wheezing and a characteristic brassy cough. (Nelson Essentials)'),
    (v_topic_id, '33: A 7-year-old female infant presents with a barking cough, hoarseness, and inspiratory stridor. The parents report a low-grade fever and rhinorrhea for the past two days. What is the most likely pathogen?', '["Streptococcus pneumoniae", "Respiratory Syncytial Virus (RSV)", "Haemophilus influenzae type b", "Parainfluenza virus"]', 3, 'Croup is most commonly caused by the Parainfluenza virus. It presents with a seal-like barking cough and inspiratory stridor due to subglottic narrowing. (Nelson Essentials)'),
    (v_topic_id, '34: What classic radiographic sign is associated with Croup on an anteroposterior (AP) neck X-ray?', '["Steeple sign", "Water bottle sign", "Sail sign", "Thumbprint sign"]', 0, 'The steeple sign (subglottic narrowing) is seen in croup on an AP neck X-ray, though the diagnosis is primarily clinical. (Blueprints)'),
    (v_topic_id, '35: A 1-year-old with a barking cough and stridor at rest is brought to the emergency department. What is the most appropriate initial medical management?', '["Immediate intubation", "Intravenous antibiotics", "Albuterol inhaler", "Nebulized racemic epinephrine and oral dexamethasone"]', 3, 'Moderate to severe croup (stridor at rest) is treated with corticosteroids (e.g., dexamethasone) to reduce inflammation and nebulized epinephrine for rapid temporary relief of airway edema. (BRS Pediatrics)'),
