    (v_topic_id, '169: Which prophylactic monoclonal antibody is indicated for infants at high risk for severe RSV bronchiolitis (e.g., premature infants, those with hemodynamically significant congenital heart disease)?', '["Infliximab", "Palivizumab", "Omalizumab", "Rituximab"]', 1, 'Palivizumab is an anti-RSV monoclonal antibody given monthly during RSV season to high-risk infants. (BRS Pediatrics)'),
